root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:80px;font-size:52px;">HIGH-NOISE<br>GLOBAL DATA</div>
  <div id="c1" style="${STY(B2)}top:430px;font-size:52px;">KRONOS MODEL<br><span style="font-size:30px;font-weight:600;margin-top:8px">45,613 GITHUB STARS</span></div>
  <div id="c2" style="${STY(B1)}top:780px;font-size:52px;">ACTIONABLE<br>TRADING FORECASTS</div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:10;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 260 L470 430" />
    <path id="l1" d="M470 610 L470 780" />
  </svg>
`;

const items = [0, 1, 2].map(i => root.querySelector('#c' + i));
const lines = [0, 1].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Cards timing: 0.0, 1.2, 2.4
  items.forEach((el, i) => {
    const s = spr(tf, i * 1.2, 0.85, 8);
    el.style.opacity = clamp(s * 2);
    const y = lerp(40, 0, E_OUT(clamp(s)));
    const scale = lerp(0.92, 1, E_OUT(clamp(s)));
    el.style.transform = `translateY(${y}px) scale(${scale})`;
  });

  // Lines timing: Start mid-way between cards
  lines.forEach((line, i) => {
    const startTime = 0.7 + (i * 1.2);
    const s = clamp((tf - startTime) * 2.5);
    const progress = E_INOUT(s);
    line.el.style.strokeDashoffset = line.len * (1 - progress);
  });
}
